def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    runs = []
    # Find the contiguous non-background line that encodes the stamp.
    for r in range(h):
        c = 0
        while c < w:
            if grid[r][c] == bg:
                c += 1; continue
            start = c
            while c < w and grid[r][c] != bg: c += 1
            if c - start >= 2:
                runs.append((c-start, 'H', r, start, [grid[r][x] for x in range(start,c)]))
    for c in range(w):
        r = 0
        while r < h:
            if grid[r][c] == bg:
                r += 1; continue
            start = r
            while r < h and grid[r][c] != bg: r += 1
            if r - start >= 2:
                runs.append((r-start, 'V', start, c, [grid[x][c] for x in range(start,r)]))
    _, axis, sr, sc, pattern = max(runs)
    stamp = {(sr + (i if axis == 'V' else 0), sc + (i if axis == 'H' else 0)) for i in range(len(pattern))}
    out = [row[:] for row in grid]
    # Remaining isolated non-background cells are target markers; center the line stamp on each.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg and (r,c) not in stamp:
                if axis == 'H':
                    for i, v in enumerate(pattern):
                        cc = c + i - len(pattern)//2
                        if 0 <= cc < w: out[r][cc] = v
                else:
                    for i, v in enumerate(pattern):
                        rr = r + i - len(pattern)//2
                        if 0 <= rr < h: out[rr][c] = v
    return out
